    "content_html": "<p><img src=\"https://drive.google.com/uc?id=1lBbhTUCPu-QAiztM0VoHhedUOwBxpYGf\" style=\"width:800px;\"></p>",
    "important": "",
    "resources": "<div class=\"mt-4 pt-4 border-t border-slate-200 dark:border-slate-700 flex flex-wrap gap-2\"><a href=\"https://drive.google.com/file/d/1PSD-0LkrcdgJ5bgl9wD63qV6APGcc1-9/preview\" target=\"_blank\" class=\"px-3 py-1.5 bg-purple-100 dark:bg-purple-900/40 text-purple-700 dark:text-purple-300 rounded text-xs font-bold hover:bg-purple-200 transition-colors\">👨‍🏫 Tutoring</a></div>",
