    "resources": "",
    "images": [],
    "local_images": [],
    "video": "https://drive.google.com/file/d/1UtZjntN1_n39wInNDAKpKu5UgecYrAvx/preview",
    "videoTitle": "Iron-Carbon Microstructures"
